@Service
public class UserServiceClient {

    private final WebClient.Builder webClientBuilder;

    @Autowired
    public UserServiceClient(WebClient.Builder webClientBuilder) {
        this.webClientBuilder = webClientBuilder;
    }

    public Mono<UserDto> getUserInfo(String token) {
        String userInfoUrl = "http://user-service/api/v1/user"; // URL для получения информации о пользователе

        // Запрос на получение информации о пользователе по токену
        return webClientBuilder.baseUrl(userInfoUrl)
                .build()
                .get()
                .header(HttpHeaders.AUTHORIZATION, "Bearer " + token)
                .retrieve()
                .bodyToMono(UserDto.class);
    }
}

